('Kadane Code','Write the C++ Kadane''s algorithm to find max subarray sum of vector<int> a, returning int.','CODING','MEDIUM','DSA','Arrays',NULL,'int kadane(vector<int>& a){int best=a[0],cur=a[0];for(int i=1;i<a.size();i++){cur=max(a[i],cur+a[i]);best=max(best,cur);}return best;}'),
('Prefix Sum Build','Write C++ code to build prefix sum array pre[] from int arr[] of size n (pre[0]=arr[0]).','CODING','MEDIUM','DSA','Arrays',NULL,'for(int i=1;i<n;i++) pre[i]=pre[i-1]+arr[i];'),
('Two Pointer Sum','Write the C++ two-pointer approach body to find if sorted array arr[] of size n has a pair summing to target. Variables l=0, r=n-1 already declared.','CODING','MEDIUM','DSA','Arrays',NULL,'while(l<r){int s=arr[l]+arr[r];if(s==target)return true;else if(s<target)l++;else r--;}return false;'),
('Rotate Three Reverse','Write C++ code to rotate array arr of size n left by k using three reversals.','CODING','MEDIUM','DSA','Arrays',NULL,'k%=n;reverse(arr,arr+k);reverse(arr+k,arr+n);reverse(arr,arr+n);'),
('Move Zeros Code','Write C++ code to move all zeros to end of array arr of size n maintaining order. Use writePos variable.','CODING','MEDIUM','DSA','Arrays',NULL,'int writePos=0;for(int i=0;i<n;i++)if(arr[i]!=0)arr[writePos++]=arr[i];while(writePos<n)arr[writePos++]=0;'),

