-- HARD CODING
('Largest Rectangle Histogram','Write the C++ monotonic stack solution for Largest Rectangle in Histogram. Function signature: int largestRect(vector<int>& h).','CODING','HARD','DSA','Arrays',NULL,'int largestRect(vector<int>& h){int n=h.size(),res=0;stack<int> st;for(int i=0;i<=n;i++){int cur=(i==n)?0:h[i];while(!st.empty()&&h[st.top()]>cur){int height=h[st.top()];st.pop();int width=st.empty()?i:i-st.top()-1;res=max(res,height*width);}st.push(i);}return res;}'),
('Trapping Rain Code','Write C++ two-pointer solution for Trapping Rain Water. Signature: int trap(vector<int>& h).','CODING','HARD','DSA','Arrays',NULL,'int trap(vector<int>& h){int l=0,r=h.size()-1,lm=0,rm=0,res=0;while(l<r){if(h[l]<h[r]){lm=max(lm,h[l]);res+=lm-h[l++];}else{rm=max(rm,h[r]);res+=rm-h[r--];}}return res;}'),
('Subarray Sum K','Write C++ O(n) solution to count subarrays with sum K using prefix sum + unordered_map. Signature: int subarraySum(vector<int>& a,int k).','CODING','HARD','DSA','Arrays',NULL,'int subarraySum(vector<int>& a,int k){unordered_map<int,int> mp;mp[0]=1;int pre=0,cnt=0;for(int x:a){pre+=x;cnt+=mp[pre-k];mp[pre]++;}return cnt;}'),
('Longest Consecutive','Write C++ O(n) solution for Longest Consecutive Sequence using unordered_set.','CODING','HARD','DSA','Arrays',NULL,'int longestConsecutive(vector<int>& a){unordered_set<int> s(a.begin(),a.end());int res=0;for(int n:s)if(!s.count(n-1)){int cur=n,len=1;while(s.count(cur+1)){cur++;len++;}res=max(res,len);}return res;}'),
('Next Greater','Write C++ O(n) Next Greater Element solution using monotonic stack. Returns vector<int> nge for input vector<int> a.','CODING','HARD','DSA','Arrays',NULL,'vector<int> nextGreater(vector<int>& a){int n=a.size();vector<int> res(n,-1);stack<int> st;for(int i=0;i<n;i++){while(!st.empty()&&a[st.top()]<a[i]){res[st.top()]=a[i];st.pop();}st.push(i);}return res;}'),

