('LL Sort','Sorting a linked list: most efficient comparison-based sort is:','MCQ','MEDIUM','DSA','Linked List','["Quick Sort — no random access so slow","Bubble Sort — simple","Merge Sort — O(n log n), works well with LL","Heap Sort — needs array"]','Merge Sort — O(n log n), works well with LL'),
('Odd Even LL','Odd-Even linked list (group all odd-position then even-position nodes) in O(n):','MCQ','MEDIUM','DSA','Linked List','["Sort by index","Two pointer: odd and even heads, weave them","Stack","Recursion"]','Two pointer: odd and even heads, weave them'),
('Swap Pairs','Swapping pairs of adjacent nodes in a linked list iteratively in O(n):','MCQ','MEDIUM','DSA','Linked List','["One pointer","Use prev, first, second pointers to swap every two nodes","Stack","Recursion only"]','Use prev, first, second pointers to swap every two nodes'),
-- MEDIUM CODING
('Floyd Detect Code','Write C++ Floyd''s cycle detection. Signature: bool hasCycle(Node* head).','CODING','MEDIUM','DSA','Linked List',NULL,'bool hasCycle(Node* head){Node* s=head,*f=head;while(f&&f->next){s=s->next;f=f->next->next;if(s==f)return true;}return false;}'),
('Reverse LL Code','Write C++ iterative reversal of linked list. Signature: Node* reverse(Node* head).','CODING','MEDIUM','DSA','Linked List',NULL,'Node* reverse(Node* head){Node* prev=nullptr,*cur=head,*nxt;while(cur){nxt=cur->next;cur->next=prev;prev=cur;cur=nxt;}return prev;}'),
('Merge Two Sorted LL','Write C++ merge of two sorted linked lists. Signature: Node* mergeSorted(Node* a, Node* b).','CODING','MEDIUM','DSA','Linked List',NULL,'Node* mergeSorted(Node* a,Node* b){if(!a)return b;if(!b)return a;if(a->data<=b->data){a->next=mergeSorted(a->next,b);return a;}b->next=mergeSorted(a,b->next);return b;}'),
('Middle LL Code','Write C++ to find the middle node of a linked list using slow/fast pointers. Signature: Node* findMiddle(Node* head).','CODING','MEDIUM','DSA','Linked List',NULL,'Node* findMiddle(Node* head){Node* slow=head,*fast=head;while(fast&&fast->next){slow=slow->next;fast=fast->next->next;}return slow;}'),
('Kth From End Code','Write C++ to find kth node from end. Use two pointers. Signature: Node* kthFromEnd(Node* head, int k).','CODING','MEDIUM','DSA','Linked List',NULL,'Node* kthFromEnd(Node* head,int k){Node* a=head,*b=head;for(int i=0;i<k;i++)a=a->next;while(a){a=a->next;b=b->next;}return b;}'),

