-- HARD CODING
('Reverse K Groups','Write C++ function to reverse nodes in K-groups. Signature: Node* reverseKGroup(Node* head, int k).','CODING','HARD','DSA','Linked List',NULL,'Node* reverseKGroup(Node* head,int k){Node* cur=head;int cnt=0;while(cur&&cnt<k){cur=cur->next;cnt++;}if(cnt<k)return head;Node* prev=nullptr,*c=head,*nxt;for(int i=0;i<k;i++){nxt=c->next;c->next=prev;prev=c;c=nxt;}head->next=reverseKGroup(c,k);return prev;}'),
('LRU Cache LL Code','Write C++ LRU Cache get(int key) using unordered_map and list<pair<int,int>>. Cache map maps key to list iterator. On hit move to front.','CODING','HARD','DSA','Linked List',NULL,'int get(int key){if(mp.find(key)==mp.end())return -1;cache.splice(cache.begin(),cache,mp[key]);return mp[key]->second;}'),
('Add Two Numbers','Write C++ to add two numbers as reversed linked lists. Signature: Node* addTwoNumbers(Node* l1, Node* l2).','CODING','HARD','DSA','Linked List',NULL,'Node* addTwoNumbers(Node* l1,Node* l2){Node dummy(0);Node* cur=&dummy;int carry=0;while(l1||l2||carry){int s=(l1?l1->data:0)+(l2?l2->data:0)+carry;carry=s/10;cur->next=new Node(s%10);cur=cur->next;if(l1)l1=l1->next;if(l2)l2=l2->next;}return dummy.next;}'),
('Palindrome Check LL','Write C++ to check if linked list is palindrome in O(n) O(1) space. Signature: bool isPalindrome(Node* head).','CODING','HARD','DSA','Linked List',NULL,'bool isPalindrome(Node* head){Node* slow=head,*fast=head;while(fast&&fast->next){slow=slow->next;fast=fast->next->next;}Node* prev=nullptr,*cur=slow;while(cur){Node* nxt=cur->next;cur->next=prev;prev=cur;cur=nxt;}Node* a=head,*b=prev;while(b){if(a->data!=b->data)return false;a=a->next;b=b->next;}return true;}'),
('Merge K Sorted LL Code','Write C++ merge K sorted lists using a min-heap. Signature: Node* mergeKLists(vector<Node*>& lists).','CODING','HARD','DSA','Linked List',NULL,'Node* mergeKLists(vector<Node*>& lists){auto cmp=[](Node* a,Node* b){return a->data>b->data;};priority_queue<Node*,vector<Node*>,decltype(cmp)> pq(cmp);for(auto h:lists)if(h)pq.push(h);Node dummy(0);Node* cur=&dummy;while(!pq.empty()){Node* top=pq.top();pq.pop();cur->next=top;cur=cur->next;if(top->next)pq.push(top->next);}return dummy.next;}'),

