('Stack Declare','Write C++ to declare a stack of integers named st and push 10 then 20.','CODING','EASY','DSA','Stack',NULL,'stack<int> st; st.push(10); st.push(20);'),
('Stack Pop Access','Write C++ to print the top of stack st, then remove it.','CODING','EASY','DSA','Stack',NULL,'cout << st.top(); st.pop();'),
('Stack Loop Print','Write C++ while-loop to print and pop all elements of stack st.','CODING','EASY','DSA','Stack',NULL,'while(!st.empty()){ cout<<st.top()<<" "; st.pop(); }'),
('Stack Balanced Simple','Write C++ to push an opening bracket to a char stack s and pop when closing bracket is found (single bracket type only, check match).','CODING','EASY','DSA','Stack',NULL,'if(c==\'(\') s.push(c); else { if(s.empty()||s.top()!=\'(\') return false; s.pop(); }'),
('Stack Reverse String','Write C++ to reverse string str using a stack<char>.','CODING','EASY','DSA','Stack',NULL,'stack<char> st; for(char c:str) st.push(c); string rev=""; while(!st.empty()){rev+=st.top();st.pop();}'),

