-- MEDIUM CODING
('Min Stack Code','Write C++ MinStack class with push(int), pop(), top(), and getMin(). Use two stacks: st and minSt.','CODING','MEDIUM','DSA','Stack',NULL,'class MinStack{stack<int> st,minSt;public:void push(int v){st.push(v);if(minSt.empty()||v<=minSt.top())minSt.push(v);}void pop(){if(st.top()==minSt.top())minSt.pop();st.pop();}int top(){return st.top();}int getMin(){return minSt.top();}};'),
('Valid Parens Code','Write C++ isValid(string s) for balanced brackets {[()]} using stack<char>.','CODING','MEDIUM','DSA','Stack',NULL,'bool isValid(string s){stack<char> st;for(char c:s){if(c==\'(\'||c==\'[\'||c==\'{\')st.push(c);else{if(st.empty())return false;char t=st.top();st.pop();if((c==\')\'&&t!=\'(\')||(c==\']\'&&t!=\'[\')||(c==\'}\'&&t!=\'{\'))return false;}}return st.empty();}'),
('Stock Span Code','Write C++ stockSpan(vector<int>& prices) returning vector<int> spans using monotonic stack of indices.','CODING','MEDIUM','DSA','Stack',NULL,'vector<int> stockSpan(vector<int>& p){int n=p.size();vector<int> res(n);stack<int> st;for(int i=0;i<n;i++){while(!st.empty()&&p[st.top()]<=p[i])st.pop();res[i]=st.empty()?i+1:i-st.top();st.push(i);}return res;}'),
('Next Greater Code','Write C++ nextGreaterElement(vector<int>& a) returning vector<int> using monotonic decreasing stack.','CODING','MEDIUM','DSA','Stack',NULL,'vector<int> nextGreaterElement(vector<int>& a){int n=a.size();vector<int> res(n,-1);stack<int> st;for(int i=0;i<n;i++){while(!st.empty()&&a[st.top()]<a[i]){res[st.top()]=a[i];st.pop();}st.push(i);}return res;}'),
('Two Stack Queue','Write C++ Queue using two stacks: enqueue(int) pushes to s1; dequeue() transfers s1 to s2 if s2 is empty then pops s2.','CODING','MEDIUM','DSA','Stack',NULL,'class MyQueue{stack<int> s1,s2;public:void enqueue(int x){s1.push(x);}int dequeue(){if(s2.empty())while(!s1.empty()){s2.push(s1.top());s1.pop();}int v=s2.top();s2.pop();return v;}};'),

